def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    my_last, opp_last = history[-1]
    cc_streak = False
    if n >= 20:
        cc_streak = True
        for i in range(n-20, n):
            if history[i][0] != 'C' or history[i][1] != 'C':
                cc_streak = False
                break
    if opp_last == 'C':
        if my_last == 'D':
            return 'D'
        if cc_streak:
            return 'D'
        return 'C'
    else:
        run_d = 0
        for i in range(n-1, -1, -1):
            if history[i][1] == 'D':
                run_d += 1
            else:
                break
        if run_d == 1:
            return 'C'
        if run_d == 2 or run_d == 3:
            return 'D'
        if run_d == 4:
            return 'C'
        return 'D'
